const input = $input.first().json;
const aiResponse = input.content?.parts?.[0]?.text || input.message?.content || input.content || JSON.stringify(input);

const webhookBody = $('Webhook').first().json.body || {};
const incomingState = webhookBody.conversationState || {};

try {
  const parsed = JSON.parse(aiResponse);

  // Build updated conversation state
  const updatedPrefs = parsed.updatedPreferences || incomingState.preferences || {};

  const newState = {
    stage: parsed.nextStage || incomingState.stage || 'discovery',
    preferences: {
      activities: updatedPrefs.activities || incomingState.preferences?.activities || [],
      style: updatedPrefs.style ?? incomingState.preferences?.style ?? null,
      climate: updatedPrefs.climate || incomingState.preferences?.climate || [],
      budget: updatedPrefs.budget ?? incomingState.preferences?.budget ?? null,
      travelers: updatedPrefs.travelers ?? incomingState.preferences?.travelers ?? 1,
      month: updatedPrefs.month ?? incomingState.preferences?.month ?? null,
      originCity: updatedPrefs.originCity ?? incomingState.preferences?.originCity ?? null,
      originIata: updatedPrefs.originIata ?? incomingState.preferences?.originIata ?? null,
    },
    shortlistedDestinations: parsed.recommendations?.length > 0 
      ? parsed.recommendations 
      : (incomingState.shortlistedDestinations || []),
    rejectedDestinationIds: incomingState.rejectedDestinationIds || [],
    confirmedDestination: parsed.confirmedDestination ?? incomingState.confirmedDestination ?? null,
    departureDate: parsed.departureDate ?? incomingState.departureDate ?? null,
    returnDate: parsed.returnDate ?? incomingState.returnDate ?? null,
    turnCount: (incomingState.turnCount || 0) + 1
  };

  return {
    json: {
      type: parsed.type || 'text',
      content: parsed.content || '',
      recommendations: parsed.recommendations || [],
      flights: [],
      shouldSearchFlights: parsed.shouldSearchFlights === true,
      conversationState: newState,
      _parsed: parsed
    }
  };
} catch (error) {
  return {
    json: {
      type: 'text',
      content: 'Lo siento, tuve un momento de confusión. ¿Puedes repetirme qué tipo de viaje buscas?',
      recommendations: [],
      flights: [],
      shouldSearchFlights: false,
      conversationState: incomingState
    }
  };
}

const state = $json.conversationState;
const confirmedDest = state.confirmedDestination;
const prefs = state.preferences;

if (!confirmedDest || !prefs.originIata) {
  return [{ json: { ...($json), _missingForFlight: true } }];
}

const isRoundTrip = !!state.returnDate;

const params = [
  ['engine', 'google_flights'],
  ['departure_id', prefs.originIata],
  ['arrival_id', confirmedDest.iata || confirmedDest.id],
  ['outbound_date', state.departureDate || (prefs.month ? prefs.month + '-01' : '')],
  ['adults', String(prefs.travelers || 1)],
  ['currency', 'USD'],
  ['hl', 'es'],
  ['gl', 'pe'],
  ['type', isRoundTrip ? '1' : '2'],
  ['deep_search', 'true'],
];

if (isRoundTrip && state.returnDate) {
  params.push(['return_date', state.returnDate]);
}

const qs = params.map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');

return [{ json: { ...($json), serpQueryString: qs } }];

const data = $input.first().json;
const prevData = $('Validate Flight Params').first().json;
const state = prevData.conversationState;

const allFlights = [...(data.best_flights || []), ...(data.other_flights || [])];

if (!allFlights.length) {
  return [{ json: { type: 'text', content: '❌ No encontré vuelos disponibles para esa ruta y fecha. ¿Quieres probar con otras fechas o un destino alternativo?', flights: [], recommendations: [], conversationState: { ...state, stage: 'date_selection' } } }];
}

const searchDate = data.search_parameters?.outbound_date || null;
const returnDate = state.returnDate || null;
const currency = data.search_parameters?.currency || 'USD';
// URL verificada: reproduce la búsqueda exacta → precios idénticos a Google Flights
const googleFlightsUrl = data.search_metadata?.google_flights_url || null;

const processed = [];
for (const option of allFlights.slice(0, 5)) {
  const segs = option.flights || [];
  if (!segs.length || !option.price) continue;

  const first = segs[0];
  const last = segs[segs.length - 1];

  // Ruta completa: LIM-BOG o LIM-MDE-BOG
  const routeParts = [first.departure_airport?.id];
  segs.forEach(f => routeParts.push(f.arrival_airport?.id));

  // Segmentos individuales
  const segments = segs.map(seg => ({
    flightNumber: seg.flight_number || 'N/A',
    airline: seg.airline || 'Unknown',
    airlineLogo: seg.airline_logo || null,
    departureAirport: seg.departure_airport?.id || '',
    departureAirportName: seg.departure_airport?.name || '',
    departureTime: seg.departure_airport?.time || '',
    arrivalAirport: seg.arrival_airport?.id || '',
    arrivalAirportName: seg.arrival_airport?.name || '',
    arrivalTime: seg.arrival_airport?.time || '',
    durationMinutes: seg.duration || 0,
    airplane: seg.airplane || null,
    cabinClass: seg.travel_class || 'Economy',
    overnight: seg.overnight || false,
  }));

  // Escalas entre segmentos
  const layovers = (option.layovers || []).map(lay => ({
    airport: lay.id || '',
    airportName: lay.name || '',
    durationMinutes: lay.duration || 0,
    overnight: lay.overnight || false,
  }));

  // Nombre de aerolínea: única si directo, combinado si hay codeshare
  const airlines = [...new Set(segs.map(s => s.airline).filter(Boolean))];
  const airlineName = airlines.join(' + ');

  // URL verificada → abre la misma búsqueda en Google Flights con precios reales
  const bookingUrl = googleFlightsUrl ||
    `https://www.google.com/travel/flights?q=Flights+from+${first.departure_airport?.id}+to+${last.arrival_airport?.id}+on+${searchDate}${returnDate ? '+returning+' + returnDate : ''}`;

  processed.push({
    flightNumber: first.flight_number || 'N/A',
    airline: airlineName,
    airlineLogo: option.airline_logo || first.airline_logo || null,
    route: routeParts.join('-'),
    originAirport: first.departure_airport?.name || null,
    destinationAirport: last.arrival_airport?.name || null,
    departureTime: first.departure_airport?.time || null,
    arrivalTime: last.arrival_airport?.time || null,
    durationMinutes: option.total_duration || null,
    stops: segs.length - 1,
    nonstop: segs.length === 1,
    price: option.price,
    currency,
    cabinClass: first.travel_class || 'Economy',
    searchDate,
    returnDate,
    bookingUrl,
    segments,
    layovers,
    trendEmoji: '➖',
    recommendation: 'Precio real',
  });
}

processed.sort((a, b) => a.price - b.price);

const dest = state.confirmedDestination;
const origin = state.preferences?.originCity;
const best = processed[0];

let content = `✈️ Encontré **${processed.length} vuelo${processed.length > 1 ? 's' : ''}** de ${origin} a ${dest?.name}`;
if (best) content += `\n\n🏆 Mejor precio: **${best.airline}** — $${best.price} USD${best.nonstop ? ' · directo' : ` · ${best.stops} escala${best.stops > 1 ? 's' : ''}`}`;

return [{ json: { type: 'flights', content, flights: processed, recommendations: dest ? [dest] : [], conversationState: { ...state, stage: 'flight_search' } } }];
